insert into guidance (event_type,given_by,text) values
  ('smilescapes','Pujya Nileshbhai','No gifts. It should not look like a marketing activity. No one should feel we are trying to convert them.'),
  ('smilescapes','Pujya Nileshbhai','Objective: people should enjoy. They should fall in love with us.'),
  ('smilescapes','Pujya Nileshbhai','Keep a few people on the sides to answer queries from passers-by.'),
  ('smilescapes','Pujya Nileshbhai','Do communication activities in a circle so the speaker can make eye contact with everyone.'),
  ('smilescapes','Pujya Nileshbhai','Return people’s money immediately, in cash, as they are leaving.'),
  ('smilescapes','Achira','No T-shirts. Concentrate on the PS outfit.');
insert into scripts (id,event_id,title,author) values ('812d756a-520e-4270-ac48-f78380c2ceec','f02a33f2-4be2-4ed2-9768-67d000eadd7c','Reel for Pujya Nileshbhai','Natasha & Chirag');
insert into script_lines (script_id,voiceover,visuals,sort) values
  ('812d756a-520e-4270-ac48-f78380c2ceec','What happens when 40 people swap their usual Saturday morning for a little adventure by the sea?','Sunrise, empty promenade, cycles being lined up',0),
  ('812d756a-520e-4270-ac48-f78380c2ceec','Well… this!','Quick montage of cycles, participants, treasure hunt and laughter',1),
  ('812d756a-520e-4270-ac48-f78380c2ceec','But before we got moving, we did something unusual.','Only text on PS blue background',2),
  ('812d756a-520e-4270-ac48-f78380c2ceec','We paused. No phones. No rushing. Just us, the sea, and a moment to ourselves.','Footage of the pause, participants looking at the sea',3),
  ('812d756a-520e-4270-ac48-f78380c2ceec','A treasure hunt. On cycles.','Music picks up – teams cycling, solving clues',4),
  ('812d756a-520e-4270-ac48-f78380c2ceec','Turns out, the best part of the ride wasn’t where we went. It was who we rode with.','Happy group shot, Smilescapes branding',5),
  ('812d756a-520e-4270-ac48-f78380c2ceec','Smilescapes by Project Smilestones.','Logo on blank screen, tagline below',6);
