insert into guidelines (category,text,sort) values
  ('Logo','RC logo sits top-left or top-centre with clear space equal to the height of the logo mark. Never stretch, recolour or add effects.',0),
  ('Logo','Smilescapes creatives use the "Smilescapes by Project Smilestones" lockup.',1),
  ('Colour','Use the event palette from the key visual. Text on Smilescapes creatives sits on PS blue.',2),
  ('Typography','Maximum two typefaces per creative. Headline at least 2× body size.',3),
  ('Mandatory info','Every external creative shows event name, date, venue and the registration link or QR.',4),
  ('Imagery','Use only approved photographs from the Library. No stock photos of people.',5),
  ('Tone','Smilescapes should not look like a marketing activity: warm, inviting, no hard sell.',6),
  ('Language','Spell-check English and Gujarati text. Use "Shrimad Rajchandra Aatma Tatva Research Centre" in full on print.',7);
